// Valida el movimiento: {"sku":"CAF-002","tipo":"entrada|venta|ajuste","cantidad":5,"nota":"opcional"}
// entrada y venta: cantidad positiva. ajuste: con signo (-2 = rotura, +3 = recuento).
const b = $json.body || {};
const sku = String(b.sku || '').trim().toUpperCase();
const tipo = String(b.tipo || '').trim().toLowerCase();
const cantidad = Number(b.cantidad);
let error = '';
if (!sku) error = 'falta sku';
else if (!['entrada', 'venta', 'ajuste'].includes(tipo)) error = 'tipo debe ser entrada, venta o ajuste';
else if (!Number.isInteger(cantidad) || cantidad === 0) error = 'cantidad debe ser un entero distinto de 0';
else if (tipo !== 'ajuste' && cantidad < 0) error = 'en entrada y venta la cantidad va en positivo';
return { json: { ok: !error, codigo: error ? 400 : 200, error, sku, tipo, cantidad, nota: String(b.nota || '').slice(0, 300) } };

const diarias = p => (Number(p.ventas_30d) || 0) / 30;
const cobertura = p => diarias(p) > 0 ? Math.floor(Number(p.stock) / diarias(p)) : null;
const sugerido = p => { const objetivo = diarias(p) > 0 ? Number(p.stock_minimo) + Math.ceil(diarias(p) * 30) : Number(p.stock_minimo) * 2;
  return Math.max(objetivo - Number(p.stock), 0); };
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = n => Number(n).toFixed(2).replace('.', ',') + ' €';
// Aplica el movimiento y decide si hay que avisar (cruza el mínimo o se agota, y hoy no se avisó de este SKU).
const m = $('Revisar movimiento').item.json;
const p = ($json.data || [])[0];
if (!p) return { json: { ...m, ok: false, codigo: 404, error: 'no existe el sku ' + m.sku } };
const antes = Number(p.stock), min = Number(p.stock_minimo);
const delta = m.tipo === 'venta' ? -m.cantidad : m.cantidad;
const despues = antes + delta;
if (despues < 0) return { json: { ...m, ok: false, codigo: 409, error: `stock insuficiente: hay ${antes} de ${m.sku}` } };
const hoy = $now.toISODate();
const cruza = antes > min && despues <= min;
const agota = antes > 0 && despues === 0;
const aviso = (cruza || agota) && p.ultimo_aviso !== hoy;
const nuevo = { ...p, stock: despues, ventas_30d: Number(p.ventas_30d || 0) + (m.tipo === 'venta' ? m.cantidad : 0) };
return { json: { ...m, ok: true, codigo: 200, producto: nuevo, stock_antes: antes, stock: despues, bajo_minimo: despues <= min, aviso,
  ultimo_aviso: aviso ? hoy : (p.ultimo_aviso || ''),
  mensaje: aviso ? [
    `${despues === 0 ? '🔴 <b>Agotado</b>' : '🟠 <b>Stock bajo</b>'} · ${esc(p.sku)} ${esc(p.nombre)}`,
    `Quedan <b>${despues}</b> (mínimo ${min}) tras ${m.tipo} de ${Math.abs(m.cantidad)}`,
    `Cobertura ≈ ${cobertura(nuevo) ?? '—'} días · ${esc(p.proveedor)}`,
    `Sugerido pedir: <b>${sugerido(nuevo)}</b> u (${eur(sugerido(nuevo) * Number(p.precio_coste))})`,
  ].join('\n') : '' } };

const diarias = p => (Number(p.ventas_30d) || 0) / 30;
const cobertura = p => diarias(p) > 0 ? Math.floor(Number(p.stock) / diarias(p)) : null;
const sugerido = p => { const objetivo = diarias(p) > 0 ? Number(p.stock_minimo) + Math.ceil(diarias(p) * 30) : Number(p.stock_minimo) * 2;
  return Math.max(objetivo - Number(p.stock), 0); };
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = n => Number(n).toFixed(2).replace('.', ',') + ' €';
// Resumen de la mañana: productos en el mínimo o por debajo, cobertura y pedido sugerido por proveedor.
// Sin mensaje si todo está bien o si ya se avisó hoy de todos (relanzamientos).
const todos = $input.all().flatMap(i => i.json.data || []);
const hoy = $now.toISODate();
const bajos = todos.filter(p => Number(p.stock) <= Number(p.stock_minimo))
  .sort((a, b) => (cobertura(a) ?? 1e9) - (cobertura(b) ?? 1e9) || Number(a.stock) - Number(b.stock));
if (!bajos.length || bajos.every(p => p.ultimo_aviso === hoy)) return [{ json: { enviar: false, bajos: bajos.length } }];
const L = [`📦 <b>Stock · ${$now.toFormat('dd/MM')}</b>`, `${bajos.length} de ${todos.length} productos en el mínimo o por debajo`, ''];
for (const p of bajos) {
  const c = cobertura(p);
  const icono = Number(p.stock) === 0 ? '🔴' : (c !== null && c <= 7) ? '🟠' : '🟡';
  L.push(`${icono} <b>${esc(p.sku)}</b> ${esc(p.nombre)} — ${p.stock} / mín ${p.stock_minimo} · ${Number(p.stock) === 0 ? 'agotado' : c === null ? 'sin ventas' : c + ' días'}`);
}
const porProveedor = {};
for (const p of bajos) {
  const n = sugerido(p); if (!n) continue;
  (porProveedor[p.proveedor || 'Sin proveedor'] ||= []).push({ p, n, coste: n * Number(p.precio_coste || 0) });
}
let total = 0;
L.push('', '<b>Pedido sugerido</b> (30 días de ventas sobre el mínimo)');
for (const [prov, lineas] of Object.entries(porProveedor).sort()) {
  const suma = lineas.reduce((s, l) => s + l.coste, 0); total += suma;
  L.push('', `<b>${esc(prov)}</b> · ${eur(suma)}`);
  for (const l of lineas) L.push(`• ${esc(l.p.sku)} ${esc(l.p.nombre)}: ${l.n} u`);
}
L.push('', `Total estimado: <b>${eur(total)}</b>`);
return [{ json: { enviar: true, texto: L.join('\n'), skus: bajos.map(p => p.sku) } }];
